import * as React from 'react'
import { cn } from '@/lib/utils'
import { optionTileClass } from '@/lib/option-tile'
import { useMergedRefs } from '@/lib/merge-refs'

export interface CheckboxGroupOption<T extends string = string> {
  value: T
  label: string
  /**
   * Optional icon rendered before the label. The DS bundles no icon library, so
   * pass the node directly (e.g. `<AppleLogo size={18} />`).
   */
  icon?: React.ReactNode
  /** Dimmed and non-interactive, but still reachable by keyboard. */
  disabled?: boolean
}

export interface CheckboxGroupProps<T extends string = string> {
  options: CheckboxGroupOption<T>[]
  /** The chosen values. Order is irrelevant; membership is what renders. */
  value: T[]
  onChange: (value: T[]) => void
  /** Names the group for assistive tech (caller-translated). */
  'aria-label'?: string
  /** Grid override. Defaults to two columns, three from `sm`. */
  className?: string
}

/**
 * Pick-any tile grid: the multi-select counterpart to `ToggleGroup`.
 *
 * `ToggleGroup` is a `radiogroup` by construction -- exactly one option, roving
 * tabindex, arrow keys to move the selection. That is the wrong widget when the
 * answer is a set, so this is a separate component rather than a `multiple` prop:
 * the ARIA roles differ, the keyboard model differs (every tile is tabbable and
 * Space toggles it, because there is no "current" option to rove from), and
 * `value` is an array.
 *
 * Both draw their tile from `optionTileClass`, so a pick-one and a pick-any
 * control look identical side by side.
 *
 * Presentational and i18n-free: pass translated labels and an `aria-label`.
 * Reaching for it means the whole set should be visible and switchable in one
 * gesture -- Icon Stack's eleven export platforms. If the set is long enough to
 * scroll, a list of switches is the better shape.
 *
 * ```tsx
 * <CheckboxGroup
 *   aria-label={t('generator.platforms')}
 *   options={PLATFORMS.map((p) => ({ value: p, label: LABELS[p], icon: <Icon /> }))}
 *   value={enabled}
 *   onChange={setEnabled}
 * />
 * ```
 */
function CheckboxGroupInner<T extends string = string>(
  { options, value, onChange, className, 'aria-label': ariaLabel }: CheckboxGroupProps<T>,
  ref: React.ForwardedRef<HTMLDivElement>,
) {
  const containerRef = React.useRef<HTMLDivElement>(null)
  const mergedRef = useMergedRefs(containerRef, ref)

  const toggle = React.useCallback(
    (option: T) => {
      onChange(value.includes(option) ? value.filter((v) => v !== option) : [...value, option])
    },
    [value, onChange],
  )

  return (
    <div
      ref={mergedRef}
      role="group"
      aria-label={ariaLabel}
      className={cn('grid grid-cols-2 gap-2 sm:grid-cols-3', className)}
    >
      {options.map((option) => {
        const checked = value.includes(option.value)
        return (
          <button
            key={option.value}
            type="button"
            // role=checkbox rather than aria-pressed: the state is "in the set"
            // or not, which is what a screen reader should hear, and it mirrors
            // ToggleGroup's radio semantics one level over.
            role="checkbox"
            aria-checked={checked}
            aria-disabled={option.disabled || undefined}
            // Kept tabbable while disabled -- see optionTileClass.
            onClick={option.disabled ? undefined : () => toggle(option.value)}
            className={cn(
              optionTileClass({ selected: checked, disabled: option.disabled }),
              // Icon beside the label, left-aligned: these are named things
              // rather than a segmented control's short verbs, so labels vary in
              // length and a centered row reads ragged.
              'touch-target justify-start gap-2 text-start',
            )}
          >
            {option.icon && (
              <span aria-hidden className="shrink-0">
                {option.icon}
              </span>
            )}
            <span className="min-w-0 truncate">{option.label}</span>
          </button>
        )
      })}
    </div>
  )
}

// forwardRef erases the generic, so re-assert it on the export: CheckboxGroup
// keeps `value`/`onChange` typed to the option union AND forwards a ref.
const CheckboxGroupWithRef = React.forwardRef(CheckboxGroupInner)
CheckboxGroupWithRef.displayName = 'CheckboxGroup'
export const CheckboxGroup = CheckboxGroupWithRef as <T extends string = string>(
  props: CheckboxGroupProps<T> & { ref?: React.Ref<HTMLDivElement> },
) => React.ReactElement
